        chase_smcath_whitemanes_chapeau = { "And his tall chapeau shouted 'ARISE!' and the {mobs} all stood up.", "And his chapeau was so holy that a little choir followed it about." },
        crit_bat_body = { "And he flapped his velvet wings so hard he rose an inch. Once.", "And he got stuck in the curtains and called it roosting." },
        crit_bat_head = { "And his bat ears picked up a whisper from three rooms away.", "And he hung upside down to sleep. The hat fell off first." },
        crit_bear_body = { "And he curled up in his bear onesie and hibernated till spring.", "And he went looking for honey and found mine." },
        crit_bear_head = { "And someone hugged his bear hat and wouldn't let go.", "And his round ears got a ribbon tied on. He kept it." },
        crit_blackflight_body = { "And his ember belly glowed when he got cross.", "And he took a deep breath for a fire breath and just coughed." },
        crit_blackflight_head = { "And his felt smoke puffed out every time he sighed.", "And he told me his auntie was Onyxia. He said it twice." },
        crit_blueflight_body = { "And he froze in place for a dramatic pose. For too long.", "And his icy belly sparkled so bright I had to squint." },
        crit_blueflight_head = { "And his frosty spikes chilled my drink. Handy.", "And he breathed on a window and drew a little snowflake." },
        crit_boar_body = { "And his curly tail uncurled when he got nervous.", "And the burlap itched so much he did a little dance." },
        crit_boar_head = { "And his boar snout sniffed out a truffle. It was a sock.", "And a tusk came unstitched and he wore it as an earring." },
        crit_bronzeflight_body = { "And he said he'd already done this bit tomorrow.", "And he turned back time to redo a joke. Still not funny." },
        crit_bronzeflight_head = { "And the tiny hourglass on his hat ran out and he panicked.", "And he told me how the dream ended. He was wrong." },
        crit_carrion_bird_body = { "And he circled me three times before saying hello.", "And he left a trail of sequins all the way home." },
        crit_carrion_bird_head = { "And his vulture hat stared at my sandwich until I gave it up.", "And his beak flopped down over his nose. He sneezed feathers." },
        crit_cat_body = { "And he pushed my drink off the table, looking right at me.", "And he chased a ball of yarn. It was his own tail unravelling." },
        crit_cat_head = { "And his cat hat's whiskers tickled my ear the whole time.", "And he purred so loudly my teeth rattled." },
        crit_centaur_body = { "And his horse tail swished a candle out at the worst time.", "And he tried to gallop and both his legs went the same way." },
        crit_centaur_head = { "And his mane got caught in the door and he neighed.", "And he tossed his yarn mane like a shampoo advert." },
        crit_crab_body = { "And he could only leave the room sideways.", "And his taped-on claw fell off and he pinched with the other." },
        crit_crab_head = { "And his wobbly eye stalks pointed two different ways.", "And it rained, and his cardboard crab hat went soft and sad." },
        crit_crocolisk_body = { "And his croc tail knocked over a whole row of chairs.", "And he lay very still in a puddle, waiting. Nobody fell for it." },
        crit_crocolisk_head = { "And his croc hat ate my hat. I never got it back.", "And {mobs} counted the felt teeth. There were too many." },
        crit_demon_body = { "And his imp tail tied itself in a bow.", "And he tried to cast a fireball and a sock came out." },
        crit_demon_head = { "And his little horns poked a hole in the ceiling.", "And he whispered something wicked. It was about pudding." },
        crit_dragonkin_body = { "And he practised his roar and it came out as a hiccup.", "And he sat on a pile of coppers, guarding it with his life." },
        crit_dragonkin_head = { "And he sneezed, and one sequin flew out like a spark.", "And his little horns caught a ring and wore it proudly." },
        crit_dwarf_body = { "And he asked {boss} for an ale in his worst Ironforge accent.", "And his belt buckle caught the light and blinded {mobs}." },
        crit_dwarf_head = { "And his yarn beard got in his soup. He drank it anyway.", "And someone tugged his beard. It was knitted to his hat." },
        crit_elemental_body = { "And they threw a bucket of water on him just in case.", "And he flickered about so much he made me dizzy." },
        crit_elemental_head = { "And somebody tried to toast bread on his felt flames.", "And he said 'BURN!' very softly so nobody would worry." },
        crit_furbolg_body = { "And he shed so much fur we could have knitted another.", "And someone mistook him for a rug and wiped their feet." },
        crit_furbolg_head = { "And his feather kept tickling his nose. He sneezed on {boss}.", "And he told me he was the friendly kind of furbolg. I believed him." },
        crit_ghost_body = { "And he said 'ooOOoo' and {mobs} said 'ooOOoo' back.", "And he tripped on his wavy hem and floated straight down." },
        crit_ghost_head = { "And his eye holes slipped round and he walked into a wall.", "And grandma came and asked for her bedsheet back." },
        crit_ghoul_body = { "And a stitch popped and stuffing went everywhere.", "And he shambled so slowly the dream ended before he arrived." },
        crit_ghoul_head = { "And his felt tongue flopped into my drink.", "And a bandage unwound and he spun round like a top." },
        crit_gnoll_body = { "And his stubby tail wagged every time someone said 'YIP'.", "And he scratched behind his ear with his foot. In public." },
        crit_gnoll_head = { "And his floppy ears flopped over his eyes. He yipped in protest.", "And he snuffled about looking for Hogger. Hogger wasn't there." },
        crit_gorilla_body = { "And he beat his chest and a button flew off.", "And he knuckle-walked all the way there. Took ages." },
        crit_gorilla_head = { "And he frowned under his big brow so hard it went flat.", "And he peeled a banana with his feet." },
        crit_greenflight_body = { "And he yawned so wide a moth flew out.", "And he curled up on the floor and snored a little green cloud." },
        crit_greenflight_head = { "And his sleepy whelp hat dozed off before he did.", "And he fell asleep in my dream and started a dream of his own." },
        crit_harpy_body = { "And his yellow bird feet slapped on the floor. Flap flap flap.", "And he tried to fly off a stool. The boas had other plans." },
        crit_harpy_head = { "And his harpy hat shrieked when he bent over.", "And he left a lilac feather in everyone's hair." },
        crit_human_body = { "And he told {boss} to move along, citizen.", "And he wrote me a ticket for loitering in a dream." },
        crit_human_head = { "And his rosy face was on upside down. Nobody said a thing.", "And {mobs} asked if he was new round here. He said yes." },
        crit_hyena_body = { "And he sniffed around the leftovers like it was his job.", "And his spiky mane stood straight up when the lights went off." },
        crit_hyena_head = { "And his hyena hat laughed at a joke I hadn't finished.", "And he cackled so long he forgot what was funny." },
        crit_kobold_body = { "And he hid a shiny rock in his pocket and told no one.", "And his rat tail swept a path through the dust." },
        crit_kobold_head = { "And his candle burnt down to the wick and he wept.", "And he blew out his own candle by mistake. Panic." },
        crit_kodo_body = { "And he stomped so hard the cups rattled off the shelf.", "And three gnomes climbed onto his back for a ride." },
        crit_kodo_head = { "And his kodo horns got stuck in the doorway. For an hour.", "And he turned round too fast and knocked out a lamp." },
        crit_murloc_body = { "And his onesie said 'MRGLGLGL' at the wrong moment.", "And his fins went flappy and splashed everyone in the front row." },
        crit_murloc_head = { "And his big round eyes fogged up from the inside.", "And he gurgled the whole national anthem. In Murloc." },
        crit_naga_body = { "And someone stood on his tail and we all went down.", "And he slithered off and left a trail of sequins." },
        crit_naga_head = { "And his fin frills twirled like he was underwater.", "And he hissed every 's' in the sentence. Ssso many." },
        crit_orc_body = { "And he said 'zug zug' and walked straight into the wall.", "And his spiky shoulder pad popped a balloon." },
        crit_orc_head = { "And his topknot came loose and fell in his eyes.", "And his felt tusks drooped when he smiled." },
        crit_quilboar_body = { "And he sat down. Then he stood up again very fast.", "And his quills stuck to the curtains on the way out." },
        crit_quilboar_head = { "And his pink snout snorted a crumb across the room.", "And {boss} patted his head and got a quill in the hand." },
        crit_raptor_body = { "And he crept up on me very slowly, clever girl.", "And his cardboard claws went clack clack all night." },
        crit_raptor_head = { "And his toothy jaw snapped shut on his own ear.", "And the tape gave up and his raptor jaw fell in the soup." },
        crit_redflight_body = { "And he gave everyone a warm hug. A bit too warm.", "And his golden belly panel shone like a big gold coin." },
        crit_redflight_head = { "And his golden horns caught the light and dazzled {mobs}.", "And he tried to look fierce, but the hat was too cute." },
        crit_satyr_body = { "And his little hooves clopped like coconut shells.", "And he pranced so much his goat legs swapped sides." },
        crit_satyr_head = { "And his ram horns spun round like a weathervane.", "And he played a tune on a twig. It was terrible." },
        crit_scorpid_body = { "And his tail curled over and bonked him on the head.", "And he snipped the ribbon at the buffet. Nobody asked him to." },
        crit_scorpid_head = { "And his pincers clacked along with the music. Off beat.", "And he pinched my nose by accident and said sorry." },
        crit_skeleton_body = { "And he rattled when he walked, though nothing was in there.", "And he did a spooky dance and his ribs slid down to his knees." },
        crit_skeleton_head = { "And they turned the lights off and his skull glowed green.", "And his toothy grin kept going after he stopped smiling." },
        crit_spider_body = { "And his eight legs got so tangled he had to be carried.", "And he hung from the ceiling on a thread. It snapped." },
        crit_spider_head = { "And all eight button eyes winked at me, one at a time.", "And he spun a web out of wool and caught a fly. And a gnome." },
        crit_tallstrider_body = { "And his skinny bird legs tangled and he fell like a deckchair.", "And he laid an egg. It was a tennis ball." },
        crit_trogg_body = { "And his stone patches clunked together like pots.", "And he lay down in a corner and nobody could find him." },
        crit_trogg_head = { "And he grunted at a rock and the rock grunted back.", "And {mobs} mistook his trogg hat for a boulder and sat on it." },
        crit_troll_body = { "And his bone necklace rattled every time he laughed.", "And his grass skirt shed a trail like a lawnmower." },
        crit_troll_head = { "And his red yarn mohawk stood up when he got excited.", "And he flicked his long ears and told me to stay frosty, mon." },
        crit_turtle_body = { "And he won the race. Everyone else had gone home.", "And he fell on his back and wiggled there till morning." },
        crit_turtle_head = { "And he pulled his head into his hat and wouldn't come out.", "And he blinked once. It took about a minute." },
        crit_wolf_body = { "And he chased his fluffy tail round and round and caught it.", "And he huffed and puffed at a door. It was already open." },
        crit_wolf_head = { "And his wolf hat howled at the lamp. The lamp didn't care.", "And grandma rang to check he was wearing it." },
        crit_zombie_body = { "And he groaned 'BRAAINS' and took a cheese scone instead.", "And he shuffled the wrong way and joined a different dream." },
        crit_zombie_head = { "And his eye on a string bounced into my drink.", "And a tuft of hair fell off and he mourned it." },
        crown_of_eternal_rest = { "And his crown made {boss} yawn, then nap right on the spot.", "And everyone round his crown fell asleep, apart from the fly." },
        dragon_hatchling_hat = { "And the baby dragon on his head sneezed and singed his eyebrows.", "And the dragon hatchling bit his ear. He said it was a kiss." },
        dragonhide_golf_jacket = { "And Onyxia's cousin turned up, very upset about his jacket.", "And his dragonhide jacket breathed fire whenever he swung his arms." },
        enchanted_jade = { "And he glowed so green in the dark I used him as a night-light.", "And a gnome tried to mine his kneecap." },
        fac_blackrock_body = { "And his plate clanked so loud {mobs} marched to it like a drum.", "And the red cloth on his belt got caught in a door. Every door." },
        fac_blackrock_head = { "And his helm's spikes popped every balloon in the place.", "And his red war paint ran when he cried at the sad bit." },
        fac_bloodsail_body = { "And his coat's brass buttons pinged off one by one, like shots.", "And he made {boss} walk the plank. There was no plank. He was sad." },
        fac_bloodsail_head = { "And his bicorne's red feather tickled his nose into a huge sneeze.", "And he turned sideways and his bicorne scraped both walls at once." },
        fac_boulderfist_body = { "And he paid for everything with rocks off his belt. They took it.", "And he high-fived {boss} and left a big yellow handprint." },
        fac_boulderfist_head = { "And he headbutted a door open with the boulder on his band.", "And the boulder on his band came loose and he chased it downhill." },
        fac_burningblade_body = { "And his fel runes lit the hem up green whenever he lied.", "And he signed me up for the Burning Blade. The forms were on fire." },
        fac_burningblade_head = { "And his hood's flames toasted a marshmallow, then his eyebrows.", "And {mobs} warmed their hands round his hood like a campfire." },
        fac_crimson_body = { "And he and a Scarlet stood side by side and made a chessboard.", "And his tabard was so white he spilled soup down it on purpose." },
        fac_crimson_head = { "And he swore his white cap was red. He'd just been washing it wrong.", "And a Scarlet asked if his cap was on inside out. It went badly." },
        fac_crushridge_body = { "And his loot sack burst and it was all spoons from Alterac.", "And bits of plundered plate fell off him. None of it was his size." },
        fac_crushridge_head = { "And his ram horns got tangled with {boss}'s and they had to waltz.", "And his fur rim was so warm he fell asleep standing up." },
        fac_darkiron_body = { "And his glowing apron set off every smoke alarm in my head.", "And he forged a horseshoe out of nothing and gave it to {boss}." },
        fac_darkiron_head = { "And his rivets glowed so bright he used his helm as a night light.", "And his Dark Iron helm went 'ding' every time he nodded off." },
        fac_deadwind_body = { "And his cracked lantern lit up only the scary bits.", "And a crow came back for one of the feathers in his cloak." },
        fac_deadwind_head = { "And his ghost mist leaked out and haunted the snack table.", "And his hood said 'boo' and he said 'boo' back, very politely." },
        fac_defias_body = { "And he used the rope off his shoulder to tie his own shoes together.", "And he said 'the Brotherhood wants you' and handed me a broom." },
        fac_defias_head = { "And his Defias mask slipped. Underneath was another Defias mask.", "And his bandana kept puffing out every time he said 'VanCleef'." },
        fac_dreadmaul_body = { "And his fel crystal made his burps come out green.", "And his chains got caught on {boss} and they went everywhere together." },
        fac_dreadmaul_head = { "And his fel glow made all the plants nearby wilt a bit.", "And he used his helm spikes to hold six sausages at once." },
        fac_dunemaul_body = { "And he poured sand out of his sleeves until we had a beach.", "And he offered round his waterskin. It was full of sand." },
        fac_dunemaul_head = { "And he unwound his head wrap to find a whole oasis in it.", "And the tail of his wrap kept slapping whoever stood behind him." },
        fac_dustbelcher_body = { "And he harpooned a cake by mistake and claimed it was a dragon.", "And he lived up to the name Dustbelcher. Twice." },
        fac_dustbelcher_head = { "And his whelp skull sneezed. We all agreed it hadn't.", "And a real whelp flew up, looked at his helm, and went pale." },
        fac_firegut_body = { "And the embers in his apron cooked my breakfast while I watched.", "And he worked his bellows at {boss} until {boss} was a bit crispy." },
        fac_firegut_head = { "And he stirred the stew in his helm and served {mobs} a bowl each.", "And his fire pot boiled over and put itself out. He sulked." },
        fac_gordok_body = { "And he took a tribute coin from everyone, me included.", "And {mobs} bowed to his sash, thinking he was King Gordok." },
        fac_gordok_head = { "And his crown fell off and all the {mobs} fought to be king.", "And a fake gem fell off his crown and {boss} tried to eat it." },
        fac_gordunni_body = { "And he read one of his stolen scrolls upside down and turned blue.", "And a night elf asked for her scrolls back. He hid behind me." },
        fac_gordunni_head = { "And his blue plume got stuck in the ceiling and he just hung there.", "And he wagged his topknot like a tail when the food came." },
        fac_kolkar_body = { "And his necklace rattled when he laughed, so we knew he'd got it.", "And he insisted he was half horse. We all looked at his legs." },
        fac_kolkar_head = { "And his headdress lost a feather every time he trotted.", "And his headdress beads clacked a rhythm and {mobs} started dancing." },
        fac_mogrosh_body = { "And a dwarf spotted his beard braids and asked if one was Grandad's.", "And he tried to mine the floor with a stolen pick. He found a coin." },
        fac_mogrosh_head = { "And his little dwarf helm got stuck and he asked a dwarf for help.", "And his wolf tail wagged on its own whenever he heard 'Loch Modan'." },
        fac_moshogg_body = { "And one of his mojo pouches opened and everyone got a bit lucky.", "And his shrunken trinkets argued with each other all night." },
        fac_moshogg_head = { "And his mask slid down and he spent the rest of it as a witch doctor.", "And his voodoo mask winked at me. He swore it didn't." },
        fac_scarlet_body = { "And his tabard got suspicious of his own shadow.", "And he tried to purify the snacks. They tasted of Light." },
        fac_scarlet_head = { "And his Scarlet cap decided I was unworthy. Then it decided you were.", "And his cap's flame badge caught the light and blinded {boss}." },
        fac_scourge_body = { "And his robes tried to recruit me. I said I'd think about it.", "And he handed out plague grain to {mobs} like party favours." },
        fac_scourge_head = { "And his cultist hood made {mobs} offer him a pamphlet. He took two.", "And his skull clasp popped open and his hood fell over his eyes." },
        fac_spirestone_body = { "And his glowing plates warmed the room so well we opened a window.", "And he hugged me and I got a red stripe from his armour." },
        fac_spirestone_head = { "And his one big horn hooked a lantern and he wore that too.", "And he tipped his stone helm to a lady and fell over." },
        fac_splinterfist_body = { "And he cracked his whip and it tied itself in a bow.", "And his broken shackles snapped onto {boss}, then fell off again." },
        fac_splinterfist_head = { "And the torch on his plank helm lit the planks. He patted it out.", "And {mobs} roasted sausages on top of his head." },
        fac_syndicate_body = { "And a hidden dagger fell out of every pouch when he sat down.", "And he picked {boss}'s pocket and found his own coin purse." },
        fac_syndicate_head = { "And his orange mask made his sneeze come out as a tiny 'pff'.", "And he pulled his hood lower and lower until he walked into {boss}." },
        fac_urok_body = { "And his worg pelts growled whenever {boss} walked past.", "And he tied his collar's broken chain to me so I wouldn't get lost." },
        fac_urok_head = { "And his worg hood got hungry and bit {boss} on the hat.", "And his worg hood howled at the moon. There wasn't a moon." },
        fac_venture_body = { "And he pulled a wrench from his belt and took the floor apart.", "And his overalls had a patch that said 'Ask me about the Barrens'." },
        fac_venture_head = { "And his hard hat's lamp kept shining right in my eyes.", "And he billed {boss} for the light from his lamp. Time is money." },
        flower_crown = { "And bees followed his flower crown everywhere he went.", "And he got peckish and ate a daisy off his own head." },
        fluffy_bathrobe = { "And his bathrobe belt came undone at the worst possible moment.", "And he was so fluffy the {mobs} kept trying to dry their hands on him." },
        gear_barrow_body = { "And the moons on his robe went from full to half to gone.", "And an owl followed his violet Barrowmoon robe around all night." },
        gear_barrow_head = { "And his moonstone circlet only glowed when nobody was looking.", "And his Moonleaf circlet dropped a silver leaf every time he sighed." },
        gear_bfd_body = { "And his puffy shell tipped him on his back like a turtle.", "And he bounced off a wall in his puffy shell, unharmed and delighted." },
        gear_bfd_head = { "And his puffy Aku'mai hood was so warm his face went pink.", "And the jaws of his Aku'mai hood closed over his face. He waited." },
        gear_brd_body = { "And his Emperor's robes made everyone bow. Even the furniture.", "And his Emperor's robes smelt faintly of Dark Iron ale." },
        gear_brd_head = { "And his Thaurissan beard was so long he tucked it into his belt.", "And he lost a spoon in his Thaurissan beard. Then found three." },
        gear_dm_body = { "And his VanCleef pauldrons were so wide he had to walk sideways.", "And his VanCleef coat jingled: every pocket full of someone's gold." },
        gear_dm_head = { "And his VanCleef mask slipped. Under it was another mask.", "And he wouldn't take off his VanCleef mask, not even to eat." },
        gear_dme_body = { "And the fel flowers on his shoulders sneezed. Then so did I.", "And his goat-fur legs went clip-clop with every step." },
        gear_dme_head = { "And his satyr horns made him headbutt things gently, like a goat.", "And someone hung their coat on his satyr horns. He let them." },
        gear_dmn_body = { "And his Ogre King furs were so warm he fell asleep standing up.", "And he swept his royal fur cloak round and knocked three things over." },
        gear_dmn_head = { "And someone bonked him and took his Gordok crown. That's the rule.", "And ogres kept bringing his Gordok crown tribute. Mostly rocks." },
        gear_dmw_body = { "And his tiger stripes turned into spots whenever he got bored.", "And his Highborne armour wouldn't be touched by commoners. Me." },
        gear_dmw_head = { "And the wind blew through his Tortheldrin hair in slow motion.", "And he flicked his Highborne hair and somebody gasped." },
        gear_excav_body = { "And his boulder shoulders rolled off and he had to chase them.", "And I knocked on his stoneskin. Someone inside said 'Busy'." },
        gear_excav_head = { "And his square stone helm made a perfect table. I put my cup on it.", "And his Guardian helm hummed one low note all dream long." },
        gear_gnomer_body = { "And his mech suit's reactor started ticking. He said it always does.", "And his mech suit ran out of fuel, so he pushed it the rest of the way" },
        gear_gnomer_head = { "And his mech goggles glowed so bright nobody needed a lamp.", "And his Mekgineer helm beeped every time he blinked." },
        gear_hyjal_body = { "And his bark armour put down roots, and he wouldn't budge.", "And his bark armour turned orange and dropped its leaves. Autumn." },
        gear_hyjal_head = { "And his antlers grew a new branch every time he laughed.", "And an apple grew on his antlers. He picked it and gave it to me." },
        gear_lbrs_body = { "And his huge Blackrock pauldrons blocked the view for everyone.", "And his red Blackrock sash came loose and he chased it like a cat." },
        gear_lbrs_head = { "And his Omokk helm was so heavy he walked in a slow circle.", "And he took off his Omokk helm. His head was just as spiky." },
        gear_mara_body = { "And a little flower grew out of his earth gown. He watered it.", "And his rock gown went THUD when he sat down. Everything shook." },
        gear_mara_head = { "And his crystal crown grew a new amethyst every time he burped.", "And his crystal crown threw purple sparkles all over my face." },
        gear_ony_body = { "And his Onyxia onesie had whelps. Little felt ones. So many whelps.", "And he flapped his floppy felt wings and went up about an inch." },
        gear_ony_head = { "And one button eye fell off his Onyxia hood and rolled away.", "And he took a deep breath in his Onyxia hood. Everyone ducked." },
        gear_rfc_body = { "And his Searing Blade robe left scorch marks wherever he sat.", "And his cult robe came with a pamphlet. He handed me one." },
        gear_rfc_head = { "And his fel horns lit the way like two little green torches.", "And his Fel Horn circlet made his ears glow green from the inside." },
        gear_rfd_body = { "And his Coldbringer shroud froze the floor, so he skated off.", "And everyone near his frosty shroud put on a jumper." },
        gear_rfd_head = { "And his ice crown melted slowly, till it was just a wet fringe.", "And his ice crown kept his drink cold. He was very proud of that." },
        gear_rfk_body = { "And his loincloth was so bristly that nobody dared to hug him.", "And his thorny armbands snagged on me, so I came along too." },
        gear_rfk_head = { "And his boar-skull helm snorted. Not him. The helm.", "And the tusks on his boar helm speared a passing pie. He ate it." },
        gear_ruins_body = { "And the velcro on his skeleton costume gave way at the worst moment.", "And someone asked what it cost, and he read it off his sleeve." },
        gear_ruins_head = { "And the satin flame on his skull hood flopped over like a sad sock.", "And the label in his skull hood said 'Ages 8 and up'." },
        gear_scholo_body = { "And a little skeleton climbed out of his robe pocket and waved.", "And the runes on his necromancer robe glowed out my homework." },
        gear_scholo_head = { "And his Darkmaster hood made everyone sit up straight and hush.", "And he took the register in his Gandling hood. I was marked absent." },
        gear_sfk_body = { "And something howled far off, and his Arugal robe howled back.", "And his Arugal robe was covered in worgen hair. He'd been hugging." },
        gear_sfk_head = { "And he vanished in his Arugal cowl, then popped up right behind me.", "And his Arugal mask hid his grin, but I knew it was there." },
        gear_smarm_body = { "And his Herod harness was cold on his bare belly. He winced.", "And he flexed in his Herod harness and a buckle pinged off." },
        gear_smarm_head = { "And his Herod helm was so shiny I fixed my hair in it.", "And his Herod helm spun round on its own, like a little whirlwind." },
        gear_smcath_body = { "And his long red gloves were for dramatic pointing only.", "And his Whitemane robes kept looking round for Mograine." },
        gear_smcath_head = { "And his Whitemane bob didn't move once. Not one hair.", "And he fell over, and his Whitemane cap brought him straight back." },
        gear_smgy_body = { "And his Thalnos robe went see-through for a moment. So did he.", "And he stamped out the flames on his robe hem. They came back." },
        gear_smgy_head = { "And the fiery lining of his Bloodmage hood toasted his bread.", "And his Bloodmage hood floated off on its own for a bit." },
        gear_smlib_body = { "And the gold stars on his robe spelled my name if you squinted.", "And he tripped on his long Scarlet robe twice, with great dignity." },
        gear_smlib_head = { "And the little gold stars came off his wizard hat and floated away.", "And he pulled a book out of his Arcanist hat and read it to me." },
        gear_st_body = { "And his dragonscale shed little green scales everywhere, like a cat.", "And his emerald scales went dark, and he whispered 'nightmare'." },
        gear_st_head = { "And his Dreamweaver circlet made him fall asleep inside my dream.", "And the emerald on his circlet winked, like it knew I was dreaming." },
        gear_stocks_body = { "And his Bazil armour had a cell key sewn into the lining.", "And every time a bell rang, his Bazil armour tried to escape." },
        gear_stocks_head = { "And he kept pulling his Bazil mask up, and it kept sliding down.", "And his Bazil hair hadn't been washed since the jailbreak." },
        gear_stratl_body = { "And his bat wings wrapped round him like a duvet when he got sleepy.", "And he flapped his Balnazzar wings and blew everyone's hair back." },
        gear_stratl_head = { "And his dreadlord horns curled a bit tighter whenever he fibbed.", "And his Balnazzar horns whispered 'trust me' to everyone." },
        gear_stratu_body = { "And his skull pauldrons argued with each other the whole time.", "And his death knight plate was freezing, so he wore it with a scarf." },
        gear_stratu_head = { "And his Rivendare helm had a timer. Forty-five minutes. He was late.", "And his Rivendare helm whinnied. There's no horse. Just the whinny." },
        gear_thanes_body = { "And his iron rings clanked like a bag of pans with every step.", "And his forearm bracers were so heavy he walked on his knuckles." },
        gear_thanes_head = { "And his red goggles made everything look rosy. He was very happy.", "And his braided red beard came undone and covered his boots." },
        gear_ubrs_body = { "And his black dragonscale was so warm I warmed my hands on him.", "And he stamped a little brand on my hand. 'For later,' he said." },
        gear_ubrs_head = { "And the fin crest on his dragon headdress caught the wind like a sail.", "And his dragon headdress was so tall he had to bow to get anywhere." },
        gear_ulda_body = { "And his stoneskin cracked, and little stone dwarves walked out.", "And he stood so still in his stoneskin I thought he was a statue." },
        gear_ulda_head = { "And his stone helm was so heavy his head sank into his shoulders.", "And the runes on his titan helm spelled out a message: 'NAP'." },
        gear_wc_body = { "And his knitted onesie got wet and stretched down to his ankles.", "And grandma's note was still pinned inside his knitted onesie." },
        gear_wc_head = { "And his knitted Mutanus hood came undone, one teal row at a time.", "And the googly eyes on his Mutanus hood kept looking at me." },
        gear_zf_body = { "And the silver horns on his troll plate hooked a hat right off.", "And his Sandscalp plate clanked so loud {mobs} heard him coming." },
        gear_zf_head = { "And his Ukorz mohawk got taller the crosser he got.", "And his red mohawk wilted in the rain. He was devastated." },
        gold = { "And his gold skin blinded the {mobs}.", "And {boss} tried to sell him to a goblin by the pound." },
        golf_polo = { "And his polo was tucked in so high it came out by his chin.", "And he kept shouting 'FORE!' at things that weren't balls." },
        grand_sleepy_pink = { "And somebody tried to blow him up like bubblegum.", "And he was so pink and soft that {boss} hugged him by accident." },
        hunt_master_body = { "And his big spiked pauldron knocked over everything on that side.", "And he drew both axes, then used one to butter his toast." },
        hunt_master_head = { "And he whistled for Misha, but only a squirrel came.", "And the tall spikes on his mask got stuck in a doorframe." },
        hunt_stalker_body = { "And he reached for an arrow and got a sandwich from his quiver.", "And his tattered cloak caught on a door and unravelled behind him." },
        hunt_stalker_head = { "And he pulled his hood up so moodily that it started to drizzle.", "And from under his hood he whispered 'for the Dark Lady', then blushed." },
        hunt_tracker_body = { "And he wrote down every one of the {mobs} in his hunting journal.", "And a cartridge popped off his bandolier and rolled under {boss}." },
        hunt_tracker_head = { "And his pith helmet kept the sun off, but not the bird nesting on it.", "And he peered out of his pith helmet and declared {boss} big game." },
        loincloth_and_member_sash = { "And he showed his member's sash to everyone, very proud of it.", "And a gust of wind came by, and he held on to his sash very tightly." },
        moss = { "And a squirrel tried to bury a nut in his mossy elbow.", "And his moss needed watering, so he stood in the rain all day." },
        mud_brown = { "And he left a muddy ogre-shaped print on everything he sat on.", "And the {mobs} thought he was a puddle and stepped in him." },
        nightcap_with_pom_pom = { "And his pom-pom bobbed so much the {mobs} got seasick.", "And a kitten swiped his pom-pom and he chased it for an hour." },
        obsidian_ember = { "And he toasted marshmallows on his own elbow.", "And he sat down and set the chair on fire. Again." },
        onesie = { "And the zip of his onesie stuck, so he had to stay in it forever.", "And he got too hot in his onesie and unzipped right down to his tummy." },
        pale_lavender = { "And the {mobs} kept sniffing him, because he looked like soap.", "And he went bright purple the second anyone said his name." },
        pirate_captain_coat = { "And a pirate turned up wanting his coat back.", "And he found a treasure map in his coat pocket. It led to my pocket." },
        royal_nap_robe = { "And the {mobs} bowed every time he yawned.", "And his royal nap robe had a train so long it got there late." },
        sea_cursed_teal = { "And a crab climbed out of his ear and walked off.", "And he dripped seawater everywhere, miles from any sea." },
        slate_gray = { "And a pigeon landed on him, sure he was a statue.", "And he stood so still the {mobs} put a plaque on him." },
        spa_towel = { "And his spa towel slipped, and the {mobs} all looked at their feet.", "And he said he was very relaxed, then sat on a wasp." },
        striped_pajamas = { "And he did his pyjama buttons up wrong, so one leg was longer.", "And the {mobs} mistook his stripes for a zebra and chased him." },
        sun_visor = { "And his sun visor kept the sun off his forehead and nothing else.", "And he wore his visor backwards. His nose fried to a crisp." },
        sunburnt_red = { "And every time someone patted his back he went 'OW'.", "And he peeled a bit and said it was a new skin." },
        swamp_green = { "And a frog moved in behind his ear and paid no rent.", "And he smelled faintly of pond, which he said was cologne." },
        tiny_top_hat = { "And his tiny top hat fell off and he had to hunt for it with a spoon.", "And he tipped his tiny top hat at {boss}, very politely." },
        towel_turban = { "And his towel turban came undone and the whole thing fell in his soup.", "And he said it was a crown now, and nobody argued." },
        tweed_vest = { "And he pulled an old pocket watch from his vest and it was a biscuit.", "And he said 'in my day' a lot, because tweed makes you say it." },
    },
