            pay = { { "And the treasure was mostly his old socks.", "And the mountain of treasure slid. With me on top.", "And the treasure belonged to a dragon. Who was home." }, { "And he took the biggest coin as a tip.", "And I lost count at four. He made me start again.", "And all the gold turned into chocolate coins. He ate them." } },
        },
        bg_barrow = {
            at = { "down in the Barrow Deeps, among the sleeping druids", "in the Barrow Deeps, trying not to wake anyone", "in the Barrow Deeps, tiptoeing past the barrow dens", "in the Barrow Deeps, tucking in a druid in bear form" },
            back = {  },
            boss = { "the oldest druid" },
            enters = { "wakes up from a thousand-year nap", "walks out of the Emerald Dream", "climbs down the roots of Nordrassil", "is snored out of a druid's dream like a sneeze" },
            mobs = { "sleeping druids", "wisps", "barrow bears" },
            pay = { { "And all the druids were dreaming about me.", "And Malfurion asked us to keep it down.", "And I fell asleep too. For a thousand years." }, { "And everyone woke up.", "And I'd been asleep for a thousand years too.", "And Ysera said this was a members-only dream." }, { "And the tiptoeing woke the whole barrow anyway.", "And the dens tiptoed after us.", "And the Emerald Dream had a nightmare about us." }, { "And the bear tucked ME in.", "And the bear asked for a bedtime story.", "And the druid turned back into an elf. Very cross." } },
        },
        bg_bfd = {
            at = { "in Blackfathom Deeps, holding my breath for way too long", "lighting the fires in Blackfathom Deeps, one by one", "in Blackfathom Deeps, being interrupted by Twilight Lord Kelris", "in Blackfathom Deeps, racing Ghamoo-ra the turtle" },
            back = { "And Lorgus Jett just went round and round in circles." },
            boss = { "Aku'mai", "Lady Sarevess" },
            enters = { "surfaces from the flooded temple", "paddles up on a turtle", "is coughed up by Old Serra'kis", "wades in with Gelihast's murlocs on his shoulders" },
            mobs = { "naga", "murlocs", "Twilight cultists" },
            pay = { { "And it turned out I could breathe the whole time.", "And he held his breath longer. Out of spite.", "And Aku'mai ate my snorkel." }, { "And all the fires went out again.", "And he lit them all with one sneeze.", "And the last fire opened the door to Aku'mai. Whoops." }, { "And Kelris asked who dared disturb his meditation. It was us.", "And Kelris put us both to sleep.", "And Kelris meditated harder. It didn't help." }, { "And Ghamoo-ra won by a whole shell.", "And the turtle took a shortcut.", "And Ghamoo-ra asked him for a rematch. Not me." } },
        },
        bg_brd = {
            at = { "in the Grim Guzzler in Blackrock Depths, on my fifth Dark Iron Ale", "in the Ring of Law in Blackrock Depths", "in Blackrock Depths, feeding Private Rocknot Dark Iron Ale", "in Blackrock Depths, rescuing Princess Moira, who didn't want rescuing" },
            back = { "And the Emperor gave him the crown. Not me.", "And the Seven were Anger, Seethe, Dope, Gloom, Vile, Hate and Doom." },
            boss = { "Emperor Thaurissan", "Plugger Spazzring" },
